# ============================================================
# USD/JPY LONG - TRANSACTION COST STRESS TEST
#
# READ-ONLY RESEARCH - NEVER SUBMITS ORDERS
#
# CURRENT LIVE vs BEST ROBUST CHALLENGER
#
# Challenger:
#   structure lookback 100
#   max distance 0.55 ATR14
#   body >= 0.80 ATR14
#   range filter OFF
#   body ratio >= 1.00
#   strong close >= 0.60
#   no EMA regime
#   no weekday exclusions
#   no session exclusions
#   RR 3.75
#
# PURPOSE
# ------------------------------------------------------------
# The current USD/JPY strategy has a slight 5Y portfolio
# compounding edge but much weaker full-history robustness.
#
# This script stresses BOTH strategies using actual per-trade
# stop distances and a range of assumed adverse entry costs.
#
# For each USD/JPY BUY:
#
#   stressed_entry =
#       reference_entry + cost_pips * 0.01
#
#   actual_risk =
#       stressed_entry - stop
#
# Winner:
#   stressed R =
#       (target - stressed_entry) / actual_risk
#
# Loser:
#   stressed R =
#       (stop - stressed_entry) / actual_risk
#
# Target remains fixed to the original reference-close RR target.
#
# Other portfolio trades are unchanged.
#
# Portfolio compounding:
#   £100 start
#   1% realised balance risk at ENTRY
#   overlapping trades retain entry risk amount
#   EXIT before ENTRY at equal timestamps
#
# Cost grid:
#   main: 0.5 / 0.75 / 1 / 1.25 / 1.5 / 2 / 2.5 / 3 pips
#   fine: 0.50 -> 4.00 pips in 0.05 increments
#
# USD/JPY pip:
#   0.01 price units
#   (tick size is 0.001, so 1 pip = 10 ticks)
# ============================================================


app = Flask(__name__)

