def read_csv_text(text):
    df = pd.read_csv(
        io.StringIO(text)
    )

    for col in [
        "entry_time_utc",
        "exit_time_utc",
    ]:
        df[col] = pd.to_datetime(
            df[col],
            utc=True,
        )

    numeric_cols = [
        "reference_entry",
        "backtest_entry",
        "stop",
        "target",
        "result_r",
        "reward_risk",
    ]

    for col in numeric_cols:
        df[col] = pd.to_numeric(
            df[col],
            errors="coerce",
        )

    return df


def current_usdjpy_buy(
    portfolio
):
    return portfolio[
        (
            portfolio[
                "instrument"
            ] == "USD_JPY"
        )
        &
        (
            portfolio[
                "side"
            ] == "BUY"
        )
    ].copy()


def restrict_window(
    df,
    start,
    end,
):
    return df[
        (
            df[
                "entry_time_utc"
            ] >= start
        )
        &
        (
            df[
                "entry_time_utc"
            ] <= end
        )
    ].copy()


def replace_usdjpy_buy(
    current,
    incoming,
):
    start = current[
        "entry_time_utc"
    ].min()

    end = current[
        "entry_time_utc"
    ].max()

    kept = current[
        ~(
            (
                current[
                    "instrument"
                ] == "USD_JPY"
            )
            &
            (
                current[
                    "side"
                ] == "BUY"
            )
        )
    ].copy()

    incoming_window = (
        restrict_window(
            incoming,
            start,
            end,
        )
    )

    out = pd.concat(
        [
            kept,
            incoming_window,
        ],
        ignore_index=True,
    )

    return (
        out.sort_values(
            [
                "entry_time_utc",
                "exit_time_utc",
                "instrument",
                "side",
            ]
        )
        .reset_index(
            drop=True
        )
    )


def stress_usdjpy_trades(
    trades,
    cost_pips,
):
    out = trades.copy()

    pip_size = 0.01

    stressed_results = []

    for _, trade in out.iterrows():
        reference_entry = float(
            trade[
                "reference_entry"
            ]
        )

        stop = float(
            trade[
                "stop"
            ]
        )

        target = float(
            trade[
                "target"
            ]
        )

        stressed_entry = (
            reference_entry
            + cost_pips
            * pip_size
        )

        actual_risk = (
            stressed_entry
            - stop
        )

        if actual_risk <= 0:
            stressed_r = None

        else:
            original_result_r = float(
                trade[
                    "result_r"
                ]
            )

            if original_result_r > 0:
                stressed_r = (
                    target
                    - stressed_entry
                ) / actual_risk
            else:
                stressed_r = (
                    stop
                    - stressed_entry
                ) / actual_risk

        stressed_results.append(
            stressed_r
        )

    out[
        "result_r"
    ] = stressed_results

    out = out.dropna(
        subset=[
            "result_r"
        ]
    )

    return out


def stats(
    df,
):
    values = (
        df[
            "result_r"
        ]
        .astype(float)
    )

    winners = values[
        values > 0
    ]

    losers = values[
        values < 0
    ]

    gross_profit = (
        winners.sum()
    )

    gross_loss = abs(
        losers.sum()
    )

    if gross_loss > 0:
        pf = (
            gross_profit
            / gross_loss
        )
    elif gross_profit > 0:
        pf = 999.0
    else:
        pf = 0.0

    total_r = (
        values.sum()
    )

    return {
        "trades":
            len(df),
        "winners":
            len(winners),
        "losers":
            len(losers),
        "win_rate":
            (
                len(winners)
                / len(df)
                * 100.0
                if len(df)
                else 0.0
            ),
        "profit_factor":
            pf,
        "total_r":
            total_r,
        "expectancy_r":
            (
                total_r
                / len(df)
                if len(df)
                else 0.0
            ),
    }


def compound(
    df,
    starting_balance=100.0,
    risk_percent=0.01,
):
    records = (
        df.reset_index(
            drop=True
        )
        .to_dict(
            "records"
        )
    )

    events = []

    for index, trade in enumerate(
        records
    ):
        entry_time = (
            pd.Timestamp(
                trade[
                    "entry_time_utc"
                ]
            ).to_pydatetime()
        )

        exit_time = (
            pd.Timestamp(
                trade[
                    "exit_time_utc"
                ]
            ).to_pydatetime()
        )

        events.append((
            entry_time,
            1,
            "ENTRY",
            index,
        ))

        events.append((
            exit_time,
            0,
            "EXIT",
            index,
        ))

    events.sort(
        key=lambda x:
            (
                x[0],
                x[1],
            )
    )

    balance = float(
        starting_balance
    )

    risk_at_entry = {}

    peak = balance
    max_dd_pct = 0.0

    for (
        event_time,
        priority,
        event_type,
        index,
    ) in events:
        trade = records[
            index
        ]

        if event_type == "ENTRY":
            risk_at_entry[
                index
            ] = (
                balance
                * risk_percent
            )

        else:
            risk_amount = (
                risk_at_entry.get(
                    index
                )
            )

            if risk_amount is None:
                continue

            balance += (
                risk_amount
                * float(
                    trade[
                        "result_r"
                    ]
                )
            )

            peak = max(
                peak,
                balance,
            )

            if peak > 0:
                dd = (
                    (
                        balance
                        - peak
                    )
                    / peak
                    * 100.0
                )

                max_dd_pct = min(
                    max_dd_pct,
                    dd,
                )

    return {
        "ending_balance":
            balance,
        "return_pct":
            (
                balance
                / starting_balance
                - 1.0
            )
            * 100.0,
        "max_closed_equity_dd_pct":
            max_dd_pct,
    }


def portfolio_at_cost(
    base,
    challenger,
    cost_pips,
    window,
):
    current_pair = (
        current_usdjpy_buy(
            base
        )
    )

    stressed_current_pair = (
        stress_usdjpy_trades(
            current_pair,
            cost_pips,
        )
    )

    stressed_challenger = (
        stress_usdjpy_trades(
            challenger,
            cost_pips,
        )
    )

    start = base[
        "entry_time_utc"
    ].min()

    end = base[
        "entry_time_utc"
    ].max()

    stressed_challenger = (
        restrict_window(
            stressed_challenger,
            start,
            end,
        )
    )

    kept = base[
        ~(
            (
                base[
                    "instrument"
                ] == "USD_JPY"
            )
            &
            (
                base[
                    "side"
                ] == "BUY"
            )
        )
    ].copy()

    current_portfolio = (
        pd.concat(
            [
                kept,
                stressed_current_pair,
            ],
            ignore_index=True,
        )
        .sort_values(
            [
                "entry_time_utc",
                "exit_time_utc",
                "instrument",
                "side",
            ]
        )
        .reset_index(
            drop=True
        )
    )

    challenger_portfolio = (
        pd.concat(
            [
                kept,
                stressed_challenger,
            ],
            ignore_index=True,
        )
        .sort_values(
            [
                "entry_time_utc",
                "exit_time_utc",
                "instrument",
                "side",
            ]
        )
        .reset_index(
            drop=True
        )
    )

    current_stats = stats(
        current_portfolio
    )

    challenger_stats = stats(
        challenger_portfolio
    )

    current_compound = compound(
        current_portfolio
    )

    challenger_compound = compound(
        challenger_portfolio
    )

    current_pair_stats = stats(
        stressed_current_pair
    )

    challenger_pair_stats = stats(
        stressed_challenger
    )

    return {
        "window":
            window,
        "cost_pips":
            cost_pips,

        "current_portfolio_trades":
            current_stats[
                "trades"
            ],
        "current_portfolio_pf":
            current_stats[
                "profit_factor"
            ],
        "current_portfolio_total_r":
            current_stats[
                "total_r"
            ],
        "current_portfolio_expectancy_r":
            current_stats[
                "expectancy_r"
            ],
        "current_ending_balance":
            current_compound[
                "ending_balance"
            ],
        "current_return_pct":
            current_compound[
                "return_pct"
            ],
        "current_max_dd_pct":
            current_compound[
                "max_closed_equity_dd_pct"
            ],

        "challenger_portfolio_trades":
            challenger_stats[
                "trades"
            ],
        "challenger_portfolio_pf":
            challenger_stats[
                "profit_factor"
            ],
        "challenger_portfolio_total_r":
            challenger_stats[
                "total_r"
            ],
        "challenger_portfolio_expectancy_r":
            challenger_stats[
                "expectancy_r"
            ],
        "challenger_ending_balance":
            challenger_compound[
                "ending_balance"
            ],
        "challenger_return_pct":
            challenger_compound[
                "return_pct"
            ],
        "challenger_max_dd_pct":
            challenger_compound[
                "max_closed_equity_dd_pct"
            ],

        "delta_total_r_challenger_minus_current":
            (
                challenger_stats[
                    "total_r"
                ]
                - current_stats[
                    "total_r"
                ]
            ),

        "delta_ending_balance_challenger_minus_current":
            (
                challenger_compound[
                    "ending_balance"
                ]
                - current_compound[
                    "ending_balance"
                ]
            ),

        "current_usdjpy_trades":
            current_pair_stats[
                "trades"
            ],
        "current_usdjpy_pf":
            current_pair_stats[
                "profit_factor"
            ],
        "current_usdjpy_total_r":
            current_pair_stats[
                "total_r"
            ],

        "challenger_usdjpy_trades":
            challenger_pair_stats[
                "trades"
            ],
        "challenger_usdjpy_pf":
            challenger_pair_stats[
                "profit_factor"
            ],
        "challenger_usdjpy_total_r":
            challenger_pair_stats[
                "total_r"
            ],
    }


def find_crossover(
    fine_df,
    window,
):
    subset = (
        fine_df[
            fine_df[
                "window"
            ] == window
        ]
        .sort_values(
            "cost_pips"
        )
        .reset_index(
            drop=True
        )
    )

    rows = []

    for metric in [
        "delta_total_r_challenger_minus_current",
        "delta_ending_balance_challenger_minus_current",
    ]:
        crossover = None

        for _, row in subset.iterrows():
            if float(
                row[
                    metric
                ]
            ) >= 0:
                crossover = float(
                    row[
                        "cost_pips"
                    ]
                )
                break

        rows.append({
            "window":
                window,
            "metric":
                metric,
            "first_cost_pips_where_challenger_ge_current":
                crossover,
            "crossover_found_within_grid":
                crossover is not None,
        })

    return rows


def run_analysis():
    try:
        STATUS.update({
            "state":
                "loading",
            "message":
                "Loading exact current portfolio and challenger trades",
        })

        base5 = read_csv_text(
            BASE5
        )

        base2 = read_csv_text(
            BASE2
        )

        challenger = read_csv_text(
            CHALLENGER_TRADES
        )

        main_rows = []
        fine_rows = []

        STATUS.update({
            "state":
                "running_main",
            "message":
                "Running main USD/JPY cost grid",
        })

        for window, base in [
            ("5Y", base5),
            ("2Y", base2),
        ]:
            for cost in MAIN_COSTS:
                main_rows.append(
                    portfolio_at_cost(
                        base,
                        challenger,
                        cost,
                        window,
                    )
                )

        STATUS.update({
            "state":
                "running_fine",
            "message":
                "Running fine USD/JPY cost grid",
        })

        for window, base in [
            ("5Y", base5),
            ("2Y", base2),
        ]:
            for cost in FINE_COSTS:
                fine_rows.append(
                    portfolio_at_cost(
                        base,
                        challenger,
                        cost,
                        window,
                    )
                )

        main_df = pd.DataFrame(
            main_rows
        )

        fine_df = pd.DataFrame(
            fine_rows
        )

        crossover_rows = []

        for window in [
            "5Y",
            "2Y",
        ]:
            crossover_rows.extend(
                find_crossover(
                    fine_df,
                    window,
                )
            )

        crossover_df = (
            pd.DataFrame(
                crossover_rows
            )
        )

        main_df.to_csv(
            os.path.abspath(
                OUTPUT_MAIN
            ),
            index=False,
        )

        fine_df.to_csv(
            os.path.abspath(
                OUTPUT_FINE
            ),
            index=False,
        )

        crossover_df.to_csv(
            os.path.abspath(
                OUTPUT_CROSSOVER
            ),
            index=False,
        )

        STATUS.update({
            "state":
                "complete",
            "message":
                "USD/JPY transaction cost stress complete",
            "outputs": {
                "main":
                    OUTPUT_MAIN,
                "fine":
                    OUTPUT_FINE,
                "crossover":
                    OUTPUT_CROSSOVER,
            },
        })

        print()
        print(
            "=" * 100
        )
        print(
            "USD/JPY TRANSACTION COST STRESS COMPLETE"
        )
        print(
            "=" * 100
        )
        print()
        print(
            main_df.to_string(
                index=False
            ),
            flush=True,
        )
        print()
        print(
            "CROSSOVER"
        )
        print(
            crossover_df.to_string(
                index=False
            ),
            flush=True,
        )

    except Exception as error:
        STATUS.update({
            "state":
                "error",
            "message":
                str(error),
        })

        print(
            "ERROR:",
            error,
            flush=True,
        )


